int process_batch(const int* data, size_t n, int** out, size_t* out_len) {
  if (!data || n == 0) { *out = NULL; *out_len = 0; return 0; }
  *out_len = n;
  *out = (int*)malloc(n * sizeof(int));
  if (!*out) return -1;
  for (size_t i = 0; i < n; ++i) (*out)[i] = data[i] * data[i];
